import argparse
import sys
from datetime import datetime

from .events import count_events, read_events, since


def parse_since(value):
    try:
        return datetime.fromisoformat(value)
    except ValueError:
        raise argparse.ArgumentTypeError(
            f"invalid date {value!r}: use YYYY-MM-DD or an ISO timestamp "
            "such as 2024-03-10T12:00:00+00:00"
        )


def build_parser():
    parser = argparse.ArgumentParser(prog="evlog")
    commands = parser.add_subparsers(dest="command", required=True)
    report = commands.add_parser("report", help="count events per service and level")
    report.add_argument("path", help="events file (JSON lines)")
    report.add_argument(
        "--since",
        type=parse_since,
        metavar="WHEN",
        help="only count events at or after this date/time (UTC unless an offset is given)",
    )
    return parser


def render(counts):
    lines = [f"{service} {level} {n}" for (service, level), n in sorted(counts.items())]
    lines.append(f"total {sum(counts.values())}")
    return "\n".join(lines)


def main(argv=None, out=None):
    out = out or sys.stdout
    parser = build_parser()
    args = parser.parse_args(argv)
    if args.command == "report":
        events = read_events(args.path)
        if args.since is not None:
            events = since(events, args.since)
        try:
            counts = count_events(events)
        except OSError as exc:
            parser.error(f"cannot read {args.path}: {exc.strerror or exc}")
        except (ValueError, KeyError) as exc:
            parser.error(f"malformed event in {args.path}: {exc!r}")
        print(render(counts), file=out)
    return 0

